# Let me check if there's diagonal connectivity rule instead
# Or maybe it's about being inside ANY closed loop of foreground

def flood_fill_bounded(grid, start_pos, bg_color, fg_color):
    """Find all cells reachable from start_pos without passing through fg_color"""
    h, w = len(grid), len(grid[0])
    visited = set()
    stack = [start_pos]

    while stack:
        i, j = stack.pop()
        if (i, j) in visited:
            continue
        if i < 0 or i >= h or j < 0 or j >= w:
            continue
        if grid[i][j] == fg_color:
            continue

        visited.add((i, j))
        for di, dj in [(0,1), (0,-1), (1,0), (-1,0)]:
            stack.append((i+di, j+dj))

    return visited

