# What if we define 'interior' as cells that CANNOT reach boundary?
# Those would be interior holes

def find_interiors(grid, bg_color, fg_color):
    """Find all background cells that cannot reach the boundary without crossing fg"""
    h, w = len(grid), len(grid[0])

    # First, mark all cells that CAN reach boundary
    can_reach_boundary = set()
    for i in range(h):
        for j in range(w):
            if grid[i][j] == bg_color:
                visited = flood_fill_bounded(grid, (i,j), bg_color, fg_color)
                if any(r in [0, h-1] or c in [0, w-1] for r,c in visited):
                    can_reach_boundary.update(visited)

    # Interior cells are those that can't reach boundary
    interiors = set()
    for i in range(h):
        for j in range(w):
            if grid[i][j] == bg_color and (i,j) not in can_reach_boundary:
                interiors.add((i,j))

    return interiors

