# Test hypothesis: fill cells that are inside a complete rectangular frame of fg color
# 
# For a cell to be filled:
# - All four orthogonal neighbors must eventually connect to form a complete loop
# - Or equivalently: the cell + its interior is enclosed by fg without gaps

def find_rectangular_interiors(grid, bg_color, fg_color):
    """Find cells strictly inside rectangular frames"""
    h, w = len(grid), len(grid[0])
    filled_cells = []

    # Check each possible top-left corner of potential rectangle
    for r1 in range(h):
        for c1 in range(w):
            if grid[r1][c1] != fg_color:
                continue
            # Try expanding this as top-left of a potential rectangle frame
            max_r, max_c = r1, c1
            for r in range(r1+1, h):
                for c in range(c1+1, w):
                    if grid[r][c] == fg_color:
                        max_r = max(max_r, r)
                        max_c = max(max_c, c)

            # Now check if [r1:r1+h_frame, c1:c1+w_frame] is fully bounded
            for r in range(r1, max_r + 1):
                for c in range(c1, max_c + 1):
                    if r == r1 or r == max_r or c == c1 or c == max_c:
                        # Should be fg_color
                        if grid[r][c] != fg_color:
                            pass  # Continue checking, incomplete frame
                    else:
                        # Interior cell
                        pass

    # Simpler approach: for each background cell, check if it's enclosed
    for i in range(h):
        for j in range(w):
            if grid[i][j] == bg_color:
                # Check via flood fill - can we escape through background?
                visited = set()
                stack = [(i, j)]

                while stack:
                    ci, cj = stack.pop()
                    if (ci, cj) in visited:
                        continue
                    if ci < 0 or ci >= h or cj < 0 or cj >= w:
                        continue
                    val = grid[ci][cj]
                    if val == fg_color:
                        continue

                    visited.add((ci, cj))

                    for di, dj in [(0,1),(0,-1),(1,0),(-1,0)]:
                        stack.append((ci+di, cj+dj))

                # If cannot reach boundary, it's interior
                reaches_boundary = any(ci in [0, h-1] or cj in [0, w-1] for ci, cj in visited)
                if not reaches_boundary:
                    # But also need to check it's truly a rectangular-like enclosure
                    filled_cells.append((i, j))

    return filled_cells

