# Final hypothesis: Fill cells that are strictly inside rectangular frames
# A rectangular frame means all 4 sides (top row, bottom row, left col, right col) 
# are contiguous segments of fg_color forming a closed loop.

def find_filled_cells(grid, bg_color, fg_color):
    h, w = len(grid), len(grid[0])
    filled = set()

    # For each potential rectangle frame
    for r_top in range(h):
        for c_left in range(w):
            if grid[r_top][c_left] != fg_color:
                continue

            # Try to build a rectangular frame from here
            for r_bottom in range(r_top + 2, h):
                if grid[r_bottom][c_left] != fg_color:
                    continue

                # Now check what width makes sense
                for c_right in range(c_left + 2, w):
                    if grid[r_top][c_right] != fg_color or grid[r_bottom][c_right] != fg_color:
                        continue

                    # Found candidate frame: corners at (r_top,c_left), (r_top,c_right), (r_bottom,c_right), (r_bottom,c_left)
                    # Now verify all sides exist (no gaps)

                    valid = True

                    # Check top row (r_top) from c_left to c_right
                    for c in range(c_left + 1, c_right):
                        if grid[r_top][c] != fg_color:
                            valid = False
                            break
                    if not valid:
                        continue

                    # Check bottom row (r_bottom)
                    for c in range(c_left + 1, c_right):
                        if grid[r_bottom][c] != fg_color:
                            valid = False
                            break
                    if not valid:
                        continue

                    # Check left col
                    for r in range(r_top + 1, r_bottom):
                        if grid[r][c_left] != fg_color:
                            valid = False
                            break
                    if not valid:
                        continue

                    # Check right col
                    for r in range(r_top + 1, r_bottom):
                        if grid[r][c_right] != fg_color:
                            valid = False
                            break
                    if not valid:
                        continue

                    # Rectangle frame is valid! Fill all interior cells
                    for r in range(r_top + 1, r_bottom):
                        for c in range(c_left + 1, c_right):
                            if grid[r][c] == bg_color:
                                filled.add((r, c))

    return filled

